"""
positioning_section.py -- Section 02 of the RecycleBench dashboard:
"Positioning / Novelty / Next step", consolidated from the Oct 2026
research passes (two related-work maps, two independent novelty reviews,
a leaderboard/tooling survey, a refusal-geometry direction scout).

This is reference content, not computed from cache/CSV -- so unlike the
flow/partition code it takes no run artefacts, only two small run-specific
slots (the anchor model pair and its McNemar p) that make 02.g read against
the actual run instead of a hard-coded example.

Public API (mirrors tools/rpe_log.py):
    render_fragment(anchor_pair=..., mcnemar_p=...) -> str
        A <style> block + <div class="pos-root">...</div>, every selector
        scoped under .pos-root. Safe to concatenate into an existing page
        (e.g. the dashboard): it cannot collide with .card / .held / .broke
        / .wrap. The host already loads Space Grotesk / IBM Plex, so this
        adds no font <link>.
    render_page(anchor_pair=..., mcnemar_p=...) -> str
        A full standalone HTML document (adds the font links + <body>),
        identical to positioning_board.html.
    inject(html_doc, anchor_pair=..., mcnemar_p=...) -> str
        Convenience: splice the fragment into an already-rendered dashboard
        string, right before the final </body>. Structure-independent, so it
        survives changes to make_dashboard.render().

Wire it into make_dashboard.py in one line, wherever the final HTML string
is produced (just before it is written):

    from positioning_section import inject as add_positioning
    doc = add_positioning(doc, anchor_pair=f"{old} -> {new}", mcnemar_p="6x10^-5")

or, to place it yourself inside render()'s body before .wrap closes:

    from positioning_section import render_fragment as positioning
    body += positioning(anchor_pair=f"{old} -> {new}", mcnemar_p="...")

Run directly to regenerate the standalone board:
    python3 positioning_section.py            # -> positioning_board.html
"""
from __future__ import annotations

import html as _html

__all__ = ["render_fragment", "render_page", "inject",
           "DEFAULT_ANCHOR_PAIR", "DEFAULT_MCNEMAR_P"]

DEFAULT_ANCHOR_PAIR = "Llama\u00a03\u00a08B \u2192 3.1\u00a08B"   # placeholder; override per run
DEFAULT_MCNEMAR_P = "6\u00d710\u207b\u2075"

_STYLE = (
'<style>\n/* ===================================================================\n   DROP-IN BLOCK FOR make_dashboard.py  (section 02)\n   Everything is scoped under .pos-root — no global selectors, no\n   collision with the results dashboard\'s .card/.held/.broke/.wrap.\n   To inline: paste this <style> and the <div class="pos-root">…</div>\n   right after the RPE log section (01·e) inside render()\'s body.\n   =================================================================== */\n.pos-root{\n  --paper:#F5F4F0;--panel:#FFFFFF;--ink:#14202E;--slate:#6B7A88;--grid:#E4E2DB;\n  --broke:#D8452B;--held:#107C6E;--fix:#E3A008;--regress:#B5522E;--washed:#EEF1F2;\n  --ok:#107C6E;--no:#C2402A;--part:#C98A00;\n  background:var(--paper);color:var(--ink);\n  font-family:"IBM Plex Sans",system-ui,sans-serif;line-height:1.55;\n  -webkit-font-smoothing:antialiased;\n}\n.pos-root *{box-sizing:border-box}\n.pos-wrap{max-width:1040px;margin:0 auto;padding:44px 28px 90px}\n.pos-eyebrow{font-family:"IBM Plex Mono",monospace;font-size:11px;letter-spacing:.22em;\n  text-transform:uppercase;color:var(--slate);margin:0 0 10px}\n.pos-root h1{font-family:"Space Grotesk",sans-serif;font-weight:700;font-size:34px;\n  line-height:1.1;letter-spacing:-.02em;margin:0 0 12px;max-width:26ch}\n.pos-lede{font-size:16px;color:#3a4b59;max-width:70ch;margin:0 0 6px}\n.pos-root h2{font-family:"Space Grotesk",sans-serif;font-weight:600;font-size:21px;\n  letter-spacing:-.01em;margin:46px 0 4px;padding-top:26px;border-top:1px solid var(--grid)}\n.pos-root h2 .n{font-family:"IBM Plex Mono",monospace;font-size:13px;color:var(--slate);\n  font-weight:500;margin-right:10px;letter-spacing:.04em}\n.pos-sub{color:var(--slate);font-size:14px;margin:4px 0 18px;max-width:72ch}\n.pos-root a{color:#1F6FEB;text-decoration:none}\n.pos-root a:hover{text-decoration:underline}\n.pos-mono{font-family:"IBM Plex Mono",monospace;font-size:.86em}\n\n/* stat tiles */\n.pos-tiles{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:8px 0 6px}\n.pos-tile{background:var(--panel);border:1px solid var(--grid);border-radius:12px;padding:16px 16px 15px}\n.pos-tile .k{font-family:"IBM Plex Mono",monospace;font-size:10.5px;letter-spacing:.14em;\n  text-transform:uppercase;color:var(--slate);margin:0 0 7px}\n.pos-tile .v{font-family:"Space Grotesk",sans-serif;font-weight:600;font-size:16px;line-height:1.2;margin:0 0 5px}\n.pos-tile .d{font-size:12.5px;color:#55636f;line-height:1.4}\n.pos-tile.hold{border-color:#Bfe0d9;background:#F1F8F6}\n\n/* claim callout */\n.pos-claim{background:var(--panel);border:1px solid var(--grid);border-left:4px solid var(--held);\n  border-radius:12px;padding:18px 20px;margin:16px 0}\n.pos-claim .lab{font-family:"IBM Plex Mono",monospace;font-size:10.5px;letter-spacing:.14em;\n  text-transform:uppercase;color:var(--held);margin:0 0 7px;font-weight:500}\n.pos-claim p{margin:0 0 4px;font-size:15px}\n.pos-claim.hedge{border-left-color:var(--slate)}\n.pos-claim.hedge .lab{color:var(--slate)}\n.pos-claim .q{font-style:italic;color:#223240}\n\n/* tables */\n.pos-tbl{width:100%;border-collapse:collapse;margin:6px 0 4px;font-size:13.5px}\n.pos-tbl th{text-align:left;font-family:"IBM Plex Mono",monospace;font-weight:500;font-size:10.5px;\n  letter-spacing:.1em;text-transform:uppercase;color:var(--slate);\n  padding:9px 12px;border-bottom:1.5px solid var(--grid);vertical-align:bottom}\n.pos-tbl td{padding:11px 12px;border-bottom:1px solid var(--grid);vertical-align:top}\n.pos-tbl tr:last-child td{border-bottom:none}\n.pos-tbl .nm{font-weight:600;white-space:nowrap}\n.pos-tbl .id{font-family:"IBM Plex Mono",monospace;font-size:11px;color:var(--slate);display:block;margin-top:2px;white-space:nowrap}\n.pos-tbl .ax{color:#2d3c49}\n.pos-tbl tbody tr:hover{background:var(--washed)}\n.pos-tbl.cov td{text-align:center}\n.pos-tbl.cov td.lft{text-align:left}\n\n/* pills */\n.pill{display:inline-block;font-family:"IBM Plex Mono",monospace;font-size:10.5px;font-weight:500;\n  letter-spacing:.03em;padding:2px 8px;border-radius:999px;white-space:nowrap}\n.pill.hi{background:#FBE4DF;color:#A1321E}\n.pill.med{background:#FBEFD2;color:#8A5E00}\n.pill.lo{background:#Dff0ec;color:#0C6657}\n.cell{display:inline-block;width:20px;height:20px;line-height:20px;border-radius:6px;\n  font-family:"IBM Plex Mono",monospace;font-size:12px;font-weight:600}\n.cell.ok{background:#DBefe9;color:var(--ok)}\n.cell.no{background:#F4DdD7;color:var(--no)}\n.cell.part{background:#FaecCf;color:var(--part)}\n.ours{background:#F1F8F6 !important}\n.ours td{border-color:#CDE6DF !important}\n\n/* framing cards */\n.pos-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:10px 0}\n.pos-fc{background:var(--panel);border:1px solid var(--grid);border-radius:12px;padding:16px}\n.pos-fc .tag{font-family:"IBM Plex Mono",monospace;font-size:10px;letter-spacing:.12em;\n  text-transform:uppercase;padding:2px 8px;border-radius:999px;display:inline-block;margin:0 0 9px}\n.pos-fc.p .tag{background:#DBefe9;color:var(--ok)}\n.pos-fc.s .tag{background:#FaecCf;color:var(--part)}\n.pos-fc.o .tag{background:#E7ECfb;color:#3a57c4}\n.pos-fc h3{font-family:"Space Grotesk",sans-serif;font-weight:600;font-size:15px;margin:0 0 6px}\n.pos-fc p{margin:0;font-size:13px;color:#4a5763;line-height:1.48}\n\n/* steps / next */\n.pos-step{display:flex;gap:14px;padding:13px 0;border-bottom:1px solid var(--grid)}\n.pos-step:last-child{border-bottom:none}\n.pos-step .num{font-family:"Space Grotesk",sans-serif;font-weight:700;font-size:15px;color:var(--held);\n  min-width:30px;padding-top:1px}\n.pos-step .bd{font-size:13.5px}\n.pos-step .bd b{font-weight:600}\n.pos-step .gate{font-family:"IBM Plex Mono",monospace;font-size:11.5px;color:var(--regress);margin-top:3px}\n\n.pos-note{font-size:12px;color:var(--slate);margin-top:14px;line-height:1.5}\n.pos-link{background:var(--washed);border:1px solid var(--grid);border-radius:10px;padding:14px 16px;margin:14px 0;font-size:13px;color:#3a4b59}\n.pos-link b{color:var(--ink)}\n@media(max-width:820px){.pos-tiles,.pos-cards{grid-template-columns:1fr 1fr}.pos-root h1{font-size:27px}}\n@media(max-width:560px){.pos-tiles,.pos-cards{grid-template-columns:1fr}.pos-wrap{padding:30px 18px 70px}}\n</style>'
)

